  p=out/'review'/f'{e["short_id"]}.html';p.parent.mkdir(exist_ok=True);p.write_text('<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>'+html.escape(e['title'])+'</title><style>body{max-width:1100px;margin:2rem auto;font:16px system-ui}pre{white-space:pre-wrap;overflow-wrap:anywhere}summary{padding:1rem;background:#eee}</style><a href="index.html">Index</a><h1>'+html.escape(e['title'])+'</h1><p>Offline answer-visible review. Fictional text evidence cards; not a blind candidate input.</p>'+''.join(sections));links.append('<li><a href="'+p.name+'">'+e['short_id']+': '+html.escape(e['title'])+'</a></li>')
